arguments.command:
ls -la output/; echo "---checking for unresolved markers---"; python3 - <<'EOF'
import docx
d = docx.Document("output/offer_letter_filled.docx")
import re
texts=[]
def walk_tables(tbls):
    for t in tbls:
        for r in t.rows:
            for c in r.cells:
                for p in c.paragraphs: texts.append(p.text)
                walk_tables(c.tables)
for p in d.paragraphs: texts.append(p.text)
walk_tables(d.tables)
for s in d.sections:
    for hf in [s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer]:
        for p in hf.paragraphs: texts.append(p.text)
        walk_tables(hf.tables)
blob="\n".join(texts)
marks=re.findall(r"\{\{[^}]*\}\}", blob)
print("Unresolved markers:", marks if marks else "NONE")
print("Has relocation amount 7,125:", "7,125" in blob)
print("Custodian present:", "Nóra Singh" in blob)
EOF
